const initState = {
    themeId: 1,
}

export const themeReducer = (state = initState, action: {type: string, themeId: number}): any => { // fix any
    switch (action.type) {
        // дописать
        case 'SET_THEME_ID':
            return {...state, themeId: action.themeId};

        default:
            return state
    }
}

type changeThemeIdActionType = {
    type: 'SET_THEME_ID',
    themeId: number
}

export const changeThemeId = (themeId: number): changeThemeIdActionType => ({ type: 'SET_THEME_ID', themeId }) // fix any