import {UserType} from '../HW8'

type ActionType =
    | { type: 'sort'; payload: 'up' | 'down' }
    | { type: 'check'; payload: number }

export const homeWorkReducer = (state: any, action: any): any => { // need to fix any
    switch (action.type) {
        case 'sort': { // by name
            let newArr = []
            if (action.payload === 'up') {
                // newArr = state.slice().sort((a: UserType, b: UserType) => a.name.localeCompare(b.name));
                newArr = [...state.sort((a: UserType, b: UserType) => a.name.localeCompare(b.name))]
            } else if (action.payload === 'down') {
                newArr = state.slice().sort((a: UserType, b: UserType) => b.name.localeCompare(a.name));
            }
            return newArr
        }
        case 'check': {
            return state.filter((person: UserType) => {
                return person.age >= 18
            })
        }
        default:
            return state
    }
}
